UPDATE `quest_template` SET `QuestDescription` = 'While you were gone, a rather shady looking human arrived at the outpost asking for you. He said he worked for... Grey was it?... and had some information regarding Spires of Arak that you would be interested in.\n\nHe was heading back to your garrison and asked that I passed along the message, and so I have.\n\nAnd before you go, thank you for all you''ve done for us here, truly. You and your army have turned the tides of a war that you could have just as easily walked away from. We will not forget.' WHERE `ID` = 35554 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
