UPDATE `quest_template` SET `QuestDescription` = 'Colossal magnaron, gronn, and other stone monstrosities have been threatening our outposts in the west. Most seem to originate from Magnarok in Frostfire Ridge.\n\nIf we strike at them at their home, we should be able to force them back. It''s risky, but it may be our best move. While you''re there, see if you can recover any of our supplies.' WHERE `ID` = 36675 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
