UPDATE `quest_template` SET `QuestDescription` = 'Botani and the plant monstrosities they conjure have been slowly encroaching on our outposts in the north. For every plant we kill, new ones seem to rise in its place.\n\nBodrick Grey has put together a plan for striking at the heart of their lands, in Everbloom Wilds. He thinks this will draw them back into the wilds of Gorgrond, giving us more room to maneuver around them.' WHERE `ID` = 36676 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
