UPDATE `quest_template` SET `QuestDescription` = 'Our base on Ashran is almost complete, commander.$b$bIt would be a huge show of support if you could make a trip out there and put your stamp of approval on their staging area.$b$bI can arrange a flight if you are interested.' WHERE `ID` = 36706 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
