UPDATE `quest_template` SET `LogDescription` = 'Kill Enemy Players in Player versus Player combat to earn 20 Broken Bones then place an offering at the Altar of Bones to Earn a Conqueror''s Tribute.' WHERE `ID` = 36874 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'Durotan...$B$B<Raza''kul spits.>$B$BHe cowers behind the white flag of peace, relying upon diplomacy to win over our sworn enemies.$B$BEnemies that have taken our homes and driven us from our ancestral lands.$B$BThere is only one way to deal with the draenei and their newfound alliance of cowards - blood for blood.$B$BJoin me in crushing our enemies. Together we will flood this hallowed ground with the bones of the Alliance and earn tributes fit for a warchief!$B$BReturn here when your bloodthirst is sated.' WHERE `ID` = 36874 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
UPDATE `quest_template` SET `LogTitle` = 'Warlord of Draenor' WHERE `ID` = 36876 AND (`LogTitle` IS NULL OR `LogTitle` = '');
UPDATE `quest_template` SET `LogDescription` = 'Kill Enemy Players in Player versus Player combat to earn 20 Broken Bones then place an offering at the Altar of Bones to Earn a Conqueror''s Tribute.' WHERE `ID` = 36876 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'The Exarchs do nothing but squabble amongst themselves over petty issues while our people are slaughtered in their homes by orc filth. If they will not raise a fist of defiance against our enemies, I will.$B$BI wish to join your Alliance and rid this world of Horde. ALL HORDE - "Iron" or otherwise.$B$BThis Altar of Bones that I stand upon represents glory in battle against our Horde enemy. Place an offering upon it and earn a conqueror''s tribute worthy of your unrelenting bloodthirst.$B$BKill. Them. All.' WHERE `ID` = 36876 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
