UPDATE `quest_template` SET `LogDescription` = 'Speak with Azik in Spires of Arak.' WHERE `ID` = 36951 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'I assume you''re familiar with the arakkoa, commander? Great, flying birdfolk. Extremely territorial.\n\nSome, however, have withered wings - a disease, maybe. They seem to be outcast from arakkoa society. You find them now and then, squatting in forgotten ruins or peddling trinkets on the roadside.\n\nIt seems the Iron Horde has incited the arakkoa by moving into their lands, and the outcasts are fleeing in droves.\n\nWe should make contact with these outcasts - they could have valuable information.' WHERE `ID` = 36951 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
UPDATE `quest_template` SET `QuestCompletionLog` = 'Speak with Azik in Spires of Arak.' WHERE `ID` = 36951 AND (`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '');
UPDATE `quest_template` SET `LogTitle` = 'Nemesis Flag, Human' WHERE `ID` = 36956 AND (`LogTitle` IS NULL OR `LogTitle` = '');
UPDATE `quest_template` SET `LogTitle` = 'Oralius'' Adventure' WHERE `ID` = 37148 AND (`LogTitle` IS NULL OR `LogTitle` = '');
UPDATE `quest_template` SET `LogDescription` = 'Collect a Spire Flamefly in Upper Blackrock Spire.' WHERE `ID` = 37148 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'Me n'' Winky, off on adventures again! This is the life, I tell ye. No burning air to breathe, an'' plenty of ogres to kill!$B$B<Oralius rubs his belly.>$B$BWe did leave a bit of a mess back there in the Blackrock Spire, though. A whole mess of these iron-plated orcs and some proto-dragons marched right on up from the south and took it over.$B$BOl'' Winky, he couldn''t take the guilt. Went on back by himself he did, to stop them!$B$BOr... to JOIN them! Winky, ye two-timing son of an orc. Ye''ve got to stop him!' WHERE `ID` = 37148 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
UPDATE `quest_template` SET `LogTitle` = 'The Void-Gate' WHERE `ID` = 37149 AND (`LogTitle` IS NULL OR `LogTitle` = '');
UPDATE `quest_template` SET `LogDescription` = 'Find a Void-Gate Key in the Shadowmoon Burial Grounds.' WHERE `ID` = 37149 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'My ''master'' is an idiot, but you look like you''ve got some smarts in that oddly-shaped head.$B$BListen up, the Twisting Nether is a chaotic abyss, and things work differently there. I''ve felt some disturbances, and they don''t bode well for any of us.$B$BYes, there are things happening here, in Draenor, that are causing ripples in the nether. No, don''t try to wrap your head around how that works, you''ll only hurt yourself.$B$BIt''s simple: bring me a Void-Gate Key, and maybe I can stop the bad things.' WHERE `ID` = 37149 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
UPDATE `quest_template` SET `LogTitle` = 'Cold Steel' WHERE `ID` = 37151 AND (`LogTitle` IS NULL OR `LogTitle` = '');
UPDATE `quest_template` SET `LogDescription` = 'Find an Iron Autocannon in Grimrail Depot.' WHERE `ID` = 37151 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'Do you know what I want? What everyone who came through that portal wants. Every soldier running from a world that didn''t understand us, didn''t need us. I want that world to love us as much as we love it.$B$BBut we don''t really belong there, not anymore. War is part of us, and we can''t go back. To everyone back there, we''re expendable.$B$BThe only thing that makes me feel better now is the feel of a cold iron cannon in my hands, pointed at the enemy.$B$B<Keeshan stares into his mug of ale.>' WHERE `ID` = 37151 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
UPDATE `quest_template` SET `LogTitle` = 'The Brass Compass' WHERE `ID` = 37155 AND (`LogTitle` IS NULL OR `LogTitle` = '');
UPDATE `quest_template` SET `LogDescription` = 'Find the Brass Compass at the Iron Docks.' WHERE `ID` = 37155 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'Greetings, commander. I have come on a mission directly from the captain.$B$BAboard any vessel on Azeroth that''s manned by at least one orc, you''ll hear sea shanties sung about a device capable of navigating the broad, rough ocean of Draenor. The orcs used it to keep their heading true in the choppiest of storms.$B$BPerhaps it''s just an old sea tale, but this one chance to find that kind of prize has the captain willing to part with some fine treasure.' WHERE `ID` = 37155 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
UPDATE `quest_template` SET `LogTitle` = 'The Soulcutter' WHERE `ID` = 37156 AND (`LogTitle` IS NULL OR `LogTitle` = '');
UPDATE `quest_template` SET `LogDescription` = 'Collect a Soulsever Blade from Auchindoun.' WHERE `ID` = 37156 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'Don''t look at me! Who do you think you are?$B$BYou and I are on the same side, you know. The necromancers here, we have to kill them. All of them.$B$BDon''t you agree?$B$BOf course you do, and you can help me accomplish this goal. Find a Soulsever Blade in that hovel where the necromancers have holed up like rats. It has... special properties... that will aid us against the undead.' WHERE `ID` = 37156 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
UPDATE `quest_template` SET `LogTitle` = 'Gloriously Incandescent' WHERE `ID` = 37158 AND (`LogTitle` IS NULL OR `LogTitle` = '');
UPDATE `quest_template` SET `LogDescription` = 'Collect a Sun Crystal in Skyreach.' WHERE `ID` = 37158 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'I did not come here to fight, I have seen too many die already. I have killed so many with my own hands.$B$BI have come to seek the light, and redemption.$B$BThe arakkoa of this land worship the sun as I do. But they are a violent, isolationist, and decadent race, who seem to derive a different message than my own people. This troubles me.$B$BBring me one of their Sun Crystals. I wish to see this light.' WHERE `ID` = 37158 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
UPDATE `quest_template` SET `LogTitle` = 'Family Traditions' WHERE `ID` = 37161 AND (`LogTitle` IS NULL OR `LogTitle` = '');
UPDATE `quest_template` SET `LogDescription` = 'Find Pip''s Improved Skinner in Blackrock Spire.' WHERE `ID` = 37161 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'He ran off with it! Oh what am I going to do, what am I going to DO?$B$BMy son, and my knife, they ran off to Blackrock Spire! Well, the knife didn''t run, I suppose. That doesn''t matter!$B$BYou''ve got to get it back! Yes, the knife! You''ve got to get me back my knife!$B$BGo! Now! Stop talking!' WHERE `ID` = 37161 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
UPDATE `quest_template` SET `LogTitle` = 'Titanic Evolution' WHERE `ID` = 37166 AND (`LogTitle` IS NULL OR `LogTitle` = '');
UPDATE `quest_template` SET `LogDescription` = 'Collect an Overgrown Artifact from The Everbloom.' WHERE `ID` = 37166 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'Ah, hello! Do not look so surprised! Did I not also brave the dangers of the Mogu''shan Vaults? I am more sturdy than I look!$B$BI have learned many things of this wonderful place in history already. Did you know that, just like on our world, the titans once came to this place?$B$BAt least, that is what I believe! Surely there are signs of the titans'' presence here, even now. Should you find one, I would very much like to see it!' WHERE `ID` = 37166 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
UPDATE `quest_template` SET `LogTitle` = 'For The Children!' WHERE `ID` = 37179 AND (`LogTitle` IS NULL OR `LogTitle` = '');
UPDATE `quest_template` SET `LogDescription` = 'Collect a Miniature Iron Star from Upper Blackrock Spire.' WHERE `ID` = 37179 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'Wait, wait! Don''t attack me! I''ve changed!$B$BReally, I''ve turned over a new leaf, I promise. I haven''t said "DOOOOOOM!" in months! All I care about now is saving the poor little orphans of Azeroth, whose parents have been taken by this tragic war.$B$BThat''s why I''m here! Why, with just a single Miniature Iron Star, I could provide clean water and power for all of the orphans of Azeroth! And no one could stop me!$B$BSo, what do you think, sweetcheeks? Want to help ol'' Milhouse save the orphans?' WHERE `ID` = 37179 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
UPDATE `quest_template` SET `LogTitle` = 'The Critical Path' WHERE `ID` = 37183 AND (`LogTitle` IS NULL OR `LogTitle` = '');
UPDATE `quest_template` SET `LogDescription` = 'Speak to Dungar Longdrink to secure a flight to Talador.' WHERE `ID` = 37183 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'The auburn forests of Talador sit at a critical crossroads of this continent, commander. The Iron Horde''s fleet is already en route from Gorgrond to Shattrath on the west coast.$B$BTalador will fall if we don''t reinforce them. I took the liberty of dispatching Foreman Eksos, who has already begun construction on an outpost for your forces not far from the Iron Horde landing point. He awaits your orders sir.' WHERE `ID` = 37183 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
UPDATE `quest_template` SET `LogTitle` = 'Taking the Fight to Nagrand' WHERE `ID` = 37184 AND (`LogTitle` IS NULL OR `LogTitle` = '');
UPDATE `quest_template` SET `LogDescription` = 'Speak with Lieutenant Balfor at the caravan in Nagrand.' WHERE `ID` = 37184 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'Commander, good to see you. With the fall of the rangari base at Telaar, Vindicator Yrel, recommended that we establish a new foothold in Nagrand.$b$bI''ve taken the liberty of dispatching some of our men and supplies. Rangari D''kaan''s already reporting that the outpost is nearly complete. He asked me to let you know they are ready for you.$b$bA gryphon is waiting to catch you up with the latest caravan shipment whenever you''re ready, $g sir:ma''am;.' WHERE `ID` = 37184 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
