UPDATE `quest_template` SET `LogDescription` = 'Speak with Kinkade Jacobs at Stormshield in Ashran.' WHERE `ID` = 37288 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'Bodrick has mentioned to me that you have acquired some interesting construction notes in your forays out there. A construction guide or assembly notes perhaps?$b$bYou should speak with Kinkade Jacobs in Stormshield. She is willing to exchange finished blueprints for such things.' WHERE `ID` = 37288 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
