UPDATE `quest_template` SET `QuestDescription` = 'Greetings commander.$b$bWord of your exploits has made its way back to Trial Master Rotun, and he has humbly requested to see your prowess in person. Fighting in his proving grounds would be an excellent way to spread your reputation to the farthest reaches of the Alliance, and beyond.$B$BIf you''re interested in proving yourself, talk to me to enter Trial Master Rotun''s Proving Grounds.' WHERE `ID` = 37433 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
