UPDATE `quest_template` SET `QuestDescription` = 'Hail commander.$b$bWord of your exploits has made its way back to Trial Master Rotun, and he has requested to see your prowess in person. Fighting in his proving grounds would be an excellent way to spread your reputation to the farthest reaches of the Horde, and beyond.$B$BIf you''re interested in proving yourself, talk to me to enter Trial Master Rotun''s Proving Grounds.' WHERE `ID` = 37434 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
