UPDATE `quest_template` SET `LogTitle` = 'Walled City: Brackenspore' WHERE `ID` = 37766 AND (`LogTitle` IS NULL OR `LogTitle` = '');
UPDATE `quest_template` SET `LogDescription` = 'Defeat Brackenspore in Highmaul.' WHERE `ID` = 37766 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'If it ain''t one threat, it''s another - I swear this light-forsaken world would try to eat us alive even without no Horde to fight.$b$bBrackenspore, ancient walker of the deep, was drawn from the waters near Highmaul by the presence of the Iron Horde. That thing is already spreading like a disease, $n. Ye got to put it down!$b$bTravel to Highmaul and defeat Brackenspore before he gets too powerful to stop.' WHERE `ID` = 37766 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
UPDATE `quest_template` SET `LogTitle` = 'Slagworks: Heart of the Mountain' WHERE `ID` = 37769 AND (`LogTitle` IS NULL OR `LogTitle` = '');
UPDATE `quest_template` SET `LogDescription` = 'Defeat the Heart of the Mountain at the Blast Furnace in Blackrock Foundry.' WHERE `ID` = 37769 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'Blackrock warriors use weapons forged in cursed fire by the breath of a creature o'' pure flame: The Heart o'' the Mountain. Let''s disarm ''em, $gboy:lass;! Destroy that infernal creature, and the Blackrock won''t have enough heat to fuel their Blast Furnace.$b$bTravel to Blackrock Foundry and defeat the Heart o'' the Mountain.' WHERE `ID` = 37769 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
UPDATE `quest_template` SET `LogTitle` = 'The Black Forge: Kromog' WHERE `ID` = 37770 AND (`LogTitle` IS NULL OR `LogTitle` = '');
UPDATE `quest_template` SET `LogDescription` = 'Defeat Kromog in Blackrock Foundry.' WHERE `ID` = 37770 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'Yer garrison scouts report that blackrock miners dug up a magnaron, and that the filthy beast has begun helpin'' those brutes churn out their infernal machines. They call it "Kromog."\n\nTravel to Blackrock Foundry and slay that fiend!' WHERE `ID` = 37770 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
UPDATE `quest_template` SET `LogTitle` = 'Iron Assembly: Admiral Gar''an' WHERE `ID` = 37771 AND (`LogTitle` IS NULL OR `LogTitle` = '');
UPDATE `quest_template` SET `LogDescription` = 'Defeat Admiral Gar''an in Blackrock Foundry.' WHERE `ID` = 37771 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = '"If ye want to topple a wall, start with the foundation." It''s an old Dwarf saying. If we take out the Iron Horde''s leadership, the whole thing tumbles.$b$bGar''an is the Admiral o'' the Iron Horde fleet and first of the so-called "Iron Maidens." She, along with her lieutenants, Marak, and Sorka, have dominated the seas of Draenor.$b$bNo more, $n. Travel to Blackrock Foundry and defeat Admiral Gar''an.' WHERE `ID` = 37771 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
UPDATE `quest_template` SET `LogTitle` = 'Death to Amethon!' WHERE `ID` = 37773 AND (`LogTitle` IS NULL OR `LogTitle` = '');
UPDATE `quest_template` SET `LogDescription` = 'Retrieve a Humming Draenite Spike from Amethon above Kuuro''s Claim in Talador.' WHERE `ID` = 37773 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'Foreman Eksos down in your Talador outpost figures he has the answer for why there''s been so much seismic activity recently.$B$BSee, there''s this giant, ah... earth fury, I think they''re called, and it''s covered in these powerful crystals in a cave up above Kuuro''s Claim. The crystals hum real loud and we think it''s driving the fury crazy!$B$BProblem is, nobody''s got the firepower to take the thing down so we can examine a sample. Think you could lend us a hand, commander?' WHERE `ID` = 37773 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
UPDATE `quest_template` SET `LogTitle` = 'Auchindoun' WHERE `ID` = 37796 AND (`LogTitle` IS NULL OR `LogTitle` = '');
UPDATE `quest_template` SET `LogDescription` = 'Defeat Teron''gor in Auchindoun.' WHERE `ID` = 37796 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'Commander, Gul''dan''s favored agent Teron''gor has infiltrated Auchindoun in Talador and has already taken to devourin'' the countless souls within. We mustn''t let this nefarious warlock gain any further strength.$B$BEnter the holy mausoleum o'' Auchindoun and rout Teron''gor and the rest o'' the Shadow Council before more damage is done.' WHERE `ID` = 37796 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
UPDATE `quest_template` SET `LogDescription` = 'Speak with Drek''Thar at the Throne of the Elements in Nagrand.' WHERE `ID` = 37840 AND (`LogDescription` IS NULL OR `LogDescription` = '');
UPDATE `quest_template` SET `QuestDescription` = 'You''ve done everything I''ve asked, $n. I believe we can apply one final enchantment to your ring. But... we must be cautious. Last time I augmented your ring I killed you. (Sorry.) It will take an act of ancient magic to empower you further.$b$bFortunately, you''ve made some powerful allies during your time here. Seek out Farseer Drek''Thar at the Throne of Elements in Nagrand. There you can receive the blessing of the elements and safely unlock your ring''s final form. Go, hero! Claim your reward!' WHERE `ID` = 37840 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
