UPDATE `quest_template` SET `QuestDescription` = 'There''s been a resurgence of rylaks on the battlefield in our skirmishes against the Iron Horde. If we don''t stop them at the source, we''ll quickly lose control of the roads and be pushed back into our outposts.\n\nThe most likely source of these additional rylaks is in southeastern Shadowmoon Valley, at Darktide Roost. If we move quickly, we should still have time to get ahead of the problem.' WHERE `ID` = 38196 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
