UPDATE `quest_template` SET `QuestDescription` = 'Nothing is left for me here. My old clanmates have turned into foes, and Gul''dan is desecrating what remains of my people.$b$bYou and your allies from Shattrath still have some fight left. If you pledge to depose Gul''dan, I will stand by your side. I will go to this garrison of yours and together we will build a shipyard that will rule the red seas of Draenor!$b$bLet your people know I am coming.' WHERE `ID` = 38258 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
