UPDATE `quest_template` SET `QuestDescription` = 'Let''s put this "Iron Shipwright" of yours to work, commander. If we''re to pull off your plan to assault Tanaan from both land and sea, we''ll need to get some docks operational as soon as possible. Work with Roark and build the Alliance a shipyard!$b$bLast I saw, Roark was northwest of the garrison, near Eventide Landing.' WHERE `ID` = 38259 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
