UPDATE `quest_template` SET `QuestDescription` = 'My warriors will surround and cover the train car. Hit the detonator to blow open the doors.$b$bI will speak to Roark and convince him to defect to our cause. He built all of this - he''s our best hope for building a shipyard of our own.$b$bIf this doesn''t work, execute him on the spot. The last thing we need is someone rebuilding the Iron Fleet.' WHERE `ID` = 38571 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
