UPDATE `quest_template` SET `QuestDescription` = 'If history is any indication, Gul''dan is training a whole generation of warlocks to marshal against us. If we act fast, we can stem the tide and make things easier on ourselves.$b$bAs you and your fellow heroes venture into the depths of the Hellfire Citadel, seek out Tomes of Chaos from Gul''dan''s lieutenants.$b$bThey''re dangerous, so don''t read any of them. Not even the pictures.$b$b<Khadgar shudders.>$b$bESPECIALLY the pictures.' WHERE `ID` = 39000 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
