UPDATE `quest_template` SET `QuestDescription` = '$n, we''ve got to destroy these tomes. Many of them have actual tortured souls bound into the pages, so we can''t just burn them. Cordana will know what to do.$b$bTake these books to my tower in Zangarra and give them to Cordana. Let me know when the deed is done.' WHERE `ID` = 39003 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
