UPDATE `quest_template` SET `QuestDescription` = 'We have one final task before us, $n. We must defeat Gul''dan and unravel his plans for this world.$b$bI have no reward to offer you - I have given you everything I can.$b$bCome. When you and your allies are ready, we march on Hellfire Citadel... and end this.' WHERE `ID` = 39004 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
