UPDATE `quest_template` SET `QuestDescription` = 'The blazing star shines upon the land, searing the earth and parching the landscape. This star is relentless, malevolent almost. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.' WHERE `ID` = 39020 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
