UPDATE `quest_template` SET `QuestDescription` = 'The chill star shines upon the land with its cold light as even the spirits retreat to the shadows. This star is unlike any other in the skies, sapping warmth and life. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.' WHERE `ID` = 39021 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
