UPDATE `quest_template` SET `QuestDescription` = 'This configuration of the stars causes an unusual vibration in the crystals strewn across Draenor, relics of the ancient Apexis. Some swear that the crystals will multiply when left unattended beneath the night sky, but none have seen the phenomenon firsthand. Regardless of the true cause, these crystals should be far more plentiful should you seek them out.' WHERE `ID` = 39033 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
