UPDATE `quest_template` SET `QuestDescription` = 'This alignment of the stars is a dire sign, stirring bloodlust and calling warriors to battle to the death in close quarters. Arena masters turn a tidy profit during these days, likely not understanding why their stands are overflowing. Amidst the excitement, great rewards do await those brave, or foolhardy, enough to venture into the arena....' WHERE `ID` = 39041 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
