UPDATE `quest_template` SET `QuestDescription` = 'Gul''dan wasted no time integrating his Shadow Council minions into every rank of the Iron Horde. The naval fleet that once owed loyalty only to Grommash is now his to command. If we want to fight back, we''re going to need more than just a couple of transport ships. We must build an arsenal.$b$bWe need your expertise, commander. Upgrade your dockyards and create a fleet capable of dominating the seas!' WHERE `ID` = 39057 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
