UPDATE `quest_template` SET `QuestDescription` = 'One of Draenor''s oldest stories is the legend of Grumpus.$B$BThe story tells of a mean-spirited brute that would come in the night, in the dead of winter, and kidnap children that misbehaved. Back at his lair, he would present them with awful toys, and use their tears to spawn his minions.$B$BBut Grumpus is no legend, he''s real and he''s taken our children! Please, you have to slay him!' WHERE `ID` = 39651 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
