UPDATE `quest_template` SET `QuestDescription` = 'That mean old Grumpus has amassed a collection of odd gifts. He''s deliberately trying to crush the spirit of children everywhere by giving out the worst presents imaginable.$B$BTake this spirit bomb. Toss it on some of Grumpus''s unusual gifts and take them out for good!$B$BWe''re in this together, $n. Now go and save the spirit of the holiday!' WHERE `ID` = 39668 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
