UPDATE `quest_template` SET `QuestDescription` = 'The Bonefleet once raided trading ships traveling the waters of Draenor. One such ship carried farming supplies intended for Elodor.$B$BNow, they use these supplies to sow their plague into our earth. From the putrid mounds sprout vegetative horrors. These abominations must be destroyed, before they can spread across the landscape.' WHERE `ID` = 39716 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
