UPDATE `quest_template` SET `QuestDescription` = 'Each year, around this time, there is a strange surge of spiritual energy across Draenor. Beckoned by this phenomenon, a ghastly fleet of undead pirates emerges from the mist. We call it the Bonefleet.$B$BThe Bonefleet is led by a savage pirate known as Bonerender. He seeks nothing more than the complete destruction of all of the living of Draenor.$B$BSeek out Bonerender and defeat him, before he sails back into the mist once again.' WHERE `ID` = 39719 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
