UPDATE `quest_template` SET `QuestDescription` = 'The Bonefleet wants nothing more than to spread their undead curse onto dry land. Like a sickness, it will slowly overtake the landscape if left unchecked.$B$BThe stench of undeath permeates the barrels of fertilizer they use to sow their dread crops. They are the source of the spreading plague, and must be destroyed.' WHERE `ID` = 39720 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
