UPDATE `quest_template` SET `QuestDescription` = 'You have proven yourself before but the wilds of Draenor are on another level. Defeat tamers in the wilds to prove your pet battle supremacy: Cymre Brightblade in Gorgrond, Vesharr in Spires of Arak, Tarr the Terrible in Nagrand, Taralune in Talador, Gargra in Frostfire Ridge, or Ashlei in Shadowmoon Valley. You can also defeat a visiting tamer: Erris the Collector or Kura Thunderhoof in your garrison.$B$BBy defeating them will show your dominance in Draenor.' WHERE `ID` = 40329 AND (`QuestDescription` IS NULL OR `QuestDescription` = '');
